<script lang="ts">
  import { currentUser } from '../auth/auth'; import { createAddress, getAddresses } from '../data/store'; import type { Address } from '../types'; let addresses = $state<Address[]>([]); let showForm = $state(false); let submitted = $state(false); let label = $state(''); let recipient = $state(''); let line1 = $state(''); let city = $state(''); let region = $state(''); let postalCode = $state(''); let phone = $state(''); let isValid = $derived(Boolean(label.trim() && recipient.trim() && line1.trim() && city.trim() && region.trim() && postalCode.trim() && phone.trim())); $effect(() => { getAddresses().then((items) => addresses = items) }); async function addAddress(event: SubmitEvent): Promise<void> { event.preventDefault(); submitted = true; if (!isValid) return; const address = await createAddress({ label, recipient, line1, city, state: region, postalCode, phone }); addresses = [...addresses, address]; showForm = false; label = ''; recipient = ''; line1 = ''; city = ''; region = ''; postalCode = ''; phone = '' }
</script>
<section class="mx-auto max-w-5xl"><p class="text-sm font-semibold text-primary">MY ACCOUNT</p><h1 class="mt-1 text-3xl font-bold text-navy">Hello, {currentUser()?.name?.split(' ')[0] ?? 'there'}</h1><div class="mt-7 grid gap-6 lg:grid-cols-3"><div class="rounded-panel bg-card p-5 ring-1 ring-line"><p class="text-sm text-muted">Account details</p><p class="mt-3 font-bold text-navy">{currentUser()?.name}</p><p class="mt-1 text-sm text-muted">{currentUser()?.email}</p><button class="mt-5 text-sm font-semibold text-primary">Edit profile</button></div><div class="lg:col-span-2"><div class="flex items-center justify-between"><h2 class="text-xl font-bold text-navy">Delivery addresses</h2><button onclick={() => showForm = !showForm} class="rounded-lg bg-primary px-4 py-2 text-sm font-semibold text-white">Add address</button></div>{#if showForm}<form onsubmit={addAddress} class="mt-4 grid gap-3 rounded-panel bg-card p-5 ring-1 ring-line sm:grid-cols-2"><input bind:value={label} class="rounded-lg border border-line px-3 py-2" placeholder="Label (e.g. Home)"/><input bind:value={recipient} class="rounded-lg border border-line px-3 py-2" placeholder="Full name"/><input bind:value={line1} class="rounded-lg border border-line px-3 py-2 sm:col-span-2" placeholder="Street address"/><input bind:value={city} class="rounded-lg border border-line px-3 py-2" placeholder="City"/><input bind:value={region} class="rounded-lg border border-line px-3 py-2" placeholder="State"/><input bind:value={postalCode} class="rounded-lg border border-line px-3 py-2" placeholder="Postal code"/><input bind:value={phone} class="rounded-lg border border-line px-3 py-2" placeholder="Phone number"/>{#if submitted && !isValid}<p class="text-sm text-danger sm:col-span-2">Please complete every address field.</p>{/if}<button disabled={!isValid} class="rounded-lg bg-primary px-4 py-2 font-semibold text-white disabled:opacity-50 sm:col-span-2">Save address</button></form>{/if}<div class="mt-4 grid gap-3 sm:grid-cols-2">{#each addresses as address (address.id)}<div class="rounded-panel bg-card p-5 ring-1 ring-line"><div class="flex justify-between"><h3 class="font-bold text-navy">{address.label}</h3>{#if address.isDefault}<span class="text-xs font-semibold text-primary">DEFAULT</span>{/if}</div><p class="mt-3 text-sm leading-6 text-muted">{address.recipient}<br/>{address.line1}<br/>{address.city}, {address.state} {address.postalCode}<br/>{address.phone}</p></div>{/each}</div></div></div></section>
